import { createM80FixtureSetup, m80HashCanonical, M80_FIXTURE_SHA256, M80_HELD_REGISTRY } from "../../packages/neuvetra-database/src/m80-fixture"
import { classifyM80Foundation, validateM80Setup } from "../../packages/neuvetra-database/src/m80-validation"
import { validateM80SaveSetup, type M80BetaSetupVersion, type M80FoundationView } from "../../packages/neuvetra-database/src/m80"

const PROFILE = "m80-scope1-beta-foundation-runtime-v1" as const
const FIXTURE_PROFILE = "m80-synthetic-scope1-foundation-v1" as const
const ACTOR = "80000000-0000-4000-8000-000000000020"
const COMPANY = /^80000000-0000-4000-8000-00000000001[01]$/
const VERSION_PATH = /^\/workspace\/(80000000-0000-4000-8000-00000000001[01])\/scope1-beta-setup(?:\/versions\/([0-9a-f-]{36}))?$/
const histories = new Map<string, M80BetaSetupVersion[]>()
const replays = new Map<string, M80BetaSetupVersion>()
const json = (status: number, value: unknown) => Response.json(value, { status, headers: { "cache-control": "no-store" } })
const admission = (companyId: string) => ({ companyId, fixtureProfileId: FIXTURE_PROFILE, fixtureVersion: 1 as const, fixtureSha256: M80_FIXTURE_SHA256, active: true })
const persisted = (setup: ReturnType<typeof validateM80Setup>) => { const { fixture: _fixture, sources, ...root } = setup; return { ...root, sources: sources.map(({ sourceIdentitySha256: _identity, ...source }) => source) } }

function foundation(companyId: string, canManage: boolean): M80FoundationView {
  const history = histories.get(companyId) ?? []
  const currentVersion = history.length ? history[history.length - 1]! : null
  const setup = currentVersion?.setup ?? validateM80Setup(createM80FixtureSetup(companyId), admission(companyId))
  const raw = persisted(setup)
  return { profile: PROFILE, syntheticOnly: true, canManage, fixtureAdmission: admission(companyId), releaseRegistry: structuredClone(M80_HELD_REGISTRY) as M80FoundationView["releaseRegistry"], currentVersion, history: history.map(({ setup: _setup, ...summary }) => summary), setup, eligibility: classifyM80Foundation(raw, admission(companyId), M80_HELD_REGISTRY) }
}

function saveVersion(companyId: string, raw: unknown) {
  const input = validateM80SaveSetup(raw), prior = histories.get(companyId) ?? []
  const replay = replays.get(`${companyId}:${input.idempotencyKey}`)
  if (replay) return { savedVersion: replay, replayed: true }
  const current = prior.length ? prior[prior.length - 1]! : null
  if (input.expectedRevision !== (current?.revision ?? 0) || input.expectedVersionId !== (current?.id ?? null) || input.expectedVersionSha256 !== (current?.versionSha256 ?? null)) throw Object.assign(new Error("conflict"), { status: 409 })
  const setup = validateM80Setup(input.setup, admission(companyId)), payloadSha256 = m80HashCanonical(persisted(setup)), createdAt = new Date().toISOString(), id = crypto.randomUUID()
  const body = { profile: PROFILE, id, companyId, reportingYear: 2025 as const, revision: prior.length + 1, previousVersionId: current?.id ?? null, previousVersionSha256: current?.versionSha256 ?? null, fixtureProfileId: FIXTURE_PROFILE, fixtureVersion: 1 as const, fixtureSha256: M80_FIXTURE_SHA256, payloadSha256, createdBy: ACTOR, createdAt, dataClassification: "synthetic_rehearsal" as const, completeness: "incomplete" as const, releasedSupportedCount: 0 as const }
  const savedVersion: M80BetaSetupVersion = { id, companyId, reportingYear: 2025, revision: body.revision, previousVersionId: body.previousVersionId, previousVersionSha256: body.previousVersionSha256, setup, payloadSha256, versionSha256: m80HashCanonical(body), createdBy: ACTOR, createdAt }
  histories.set(companyId, [...prior, savedVersion]); replays.set(`${companyId}:${input.idempotencyKey}`, savedVersion)
  return { savedVersion, replayed: false }
}

const server = Bun.serve({
  hostname: "127.0.0.1", port: 5199,
  async fetch(request) {
    const url = new URL(request.url), match = VERSION_PATH.exec(url.pathname), authorization = request.headers.get("authorization")
    if (!match || !COMPANY.test(match[1]!)) return json(404, { error: "Scope 1 beta setup not found." })
    if (!authorization?.startsWith("Bearer mock-")) return json(401, { error: "Authentication required." })
    if (authorization === "Bearer mock-error") return json(503, { error: "Mock server error for recovery review." })
    if (authorization === "Bearer mock-slow") await Bun.sleep(1_500)
    const companyId = match[1]!, versionId = match[2] ?? null, canManage = authorization === "Bearer mock-manager"
    if (request.method === "GET" && versionId) {
      const version = (histories.get(companyId) ?? []).find(item => item.id === versionId)
      return version ? json(200, version) : json(404, { error: "Scope 1 beta setup not found." })
    }
    if (request.method === "GET") return json(200, foundation(companyId, canManage))
    if (request.method !== "POST" || versionId) return json(405, { error: "Method not allowed." })
    if (!canManage) return json(403, { error: "Forbidden." })
    try {
      const saved = saveVersion(companyId, await request.json())
      return json(saved.replayed ? 200 : 201, { foundation: foundation(companyId, true), ...saved })
    } catch (error) {
      if ((error as { status?: number }).status === 409) return json(409, { error: "Scope 1 beta setup changed. Refresh current setup." })
      return json(422, { error: error instanceof Error ? error.message : "Invalid mock setup request." })
    }
  },
})
console.log(`M80 synthetic mock API listening on ${server.url}`)

import path from "node:path"
import { fileURLToPath } from "node:url"
import base from "../../apps/site-web/vite.config"

const previewDir = path.dirname(fileURLToPath(import.meta.url))
const appDir = path.resolve(previewDir, "../../apps/site-web")
const previewEntry = path.resolve(previewDir, "main.tsx").replaceAll("\\", "/")
const previewPlugin = {
  name: "m80-setup-preview",
  configureServer(server: { middlewares: { use: (handler: (request: { url?: string }, response: { statusCode: number; setHeader: (name: string, value: string) => void; end: (value: string) => void }, next: () => void) => void) => void } }) {
    server.middlewares.use((request, response, next) => {
      if (request.url !== "/m80-preview/" && request.url !== "/m80-preview") return next()
      response.statusCode = 200
      response.setHeader("content-type", "text/html; charset=utf-8")
      response.end(`<!doctype html><html lang="en" style="background:#0b0c0d"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>M80 Scope 1 setup mock preview</title></head><body><div id="root"></div><script type="module" src="/@fs/${previewEntry}"></script></body></html>`)
    })
  },
}

export default {
  ...base,
  root: appDir,
  plugins: [...(base.plugins ?? []), previewPlugin],
  server: {
    ...base.server,
    host: "127.0.0.1",
    port: 5198,
    strictPort: true,
    fs: { strict: true, allow: [appDir, previewDir] },
    proxy: { "/workspace-api": { target: "http://127.0.0.1:5199", rewrite: (value: string) => value.replace(/^\/workspace-api/, "") } },
  },
}
